{
  "title": "Silent data-center escape",
  "tempo_map": [
    {"bar": 1, "bpm": 100},
    {"bar": 21, "bpm": 125}
  ],
  "key_map": [
    {"bar": 1, "key": "A minor"}
  ],
  "sections": [
    {"id": "infiltration", "start_bar": 1, "bars": 8},
    {"id": "near_miss", "start_bar": 9, "bars": 8},
    {"id": "decision", "start_bar": 17, "bars": 4},
    {"id": "sprint", "start_bar": 21, "bars": 12},
    {"id": "cut", "start_bar": 33, "bars": 2}
  ],
  "track_plan": [
    {
      "id": "sub_pulse",
      "name": "Sub Pulse",
      "role": "bass",
      "register": {"low": 24, "high": 48},
      "instrument_hint": "sine sub bass with short envelope",
      "section_jobs": [
        {"section_id": "infiltration", "intent": "sparse sub roots on downbeats, occasional offbeat push", "density": "sparse"},
        {"section_id": "near_miss", "intent": "reduce to silence, only one low hit at edit point", "density": "sparse"},
        {"section_id": "decision", "intent": "short two-note pattern, rising tension", "density": "medium"},
        {"section_id": "sprint", "intent": "driving eighth-note pulse with gaps", "density": "dense"},
        {"section_id": "cut", "intent": "final sub hit on downbeat then silence", "density": "sparse"}
      ]
    },
    {
      "id": "muted_perc",
      "name": "Muted Percussion",
      "role": "percussion",
      "register": {"low": 36, "high": 72},
      "instrument_hint": "muffled kicks, toms, rim clicks",
      "section_jobs": [
        {"section_id": "infiltration", "intent": "dry kicks and rim clicks, syncopated but sparse", "density": "medium"},
        {"section_id": "near_miss", "intent": "only two or three hits, negative space", "density": "sparse"},
        {"section_id": "decision", "intent": "build with tom pattern, still sparse", "density": "medium"},
        {"section_id": "sprint", "intent": "steady but broken four-on-floor with fills", "density": "dense"},
        {"section_id": "cut", "intent": "one impact, no fill", "density": "sparse"}
      ]
    },
    {
      "id": "high_tick",
      "name": "High Tick",
      "role": "percussion",
      "register": {"low": 72, "high": 96},
      "instrument_hint": "short metallic tick, clave, tiny shaker",
      "section_jobs": [
        {"section_id": "infiltration", "intent": "off-beat 16th ticks every other bar", "density": "sparse"},
        {"section_id": "near_miss", "intent": "single tick at phrase end", "density": "sparse"},
        {"section_id": "decision", "intent": "increase to 8th-note ticks, panned", "density": "medium"},
        {"section_id": "sprint", "intent": "constant 16th-note tick layer with velocity variation", "density": "dense"},
        {"section_id": "cut", "intent": "one high tick on final cut", "density": "sparse"}
      ]
    },
    {
      "id": "dark_harmony",
      "name": "Dark Harmony",
      "role": "harmony",
      "register": {"low": 48, "high": 72},
      "instrument_hint": "dark pad, low strings or filtered keys",
      "section_jobs": [
        {"section_id": "infiltration", "intent": "sustained minor pad, slow changes", "density": "medium"},
        {"section_id": "near_miss", "intent": "only one dark cluster, very low dynamic", "density": "sparse"},
        {"section_id": "decision", "intent": "two-chord swell, rising", "density": "medium"},
        {"section_id": "sprint", "intent": "rhythmic stabs, syncopated chords", "density": "dense"},
        {"section_id": "cut", "intent": "final dissonant stab cut off", "density": "sparse"}
      ]
    },
    {
      "id": "motif",
      "name": "Motif",
      "role": "melody",
      "register": {"low": 60, "high": 84},
      "instrument_hint": "breathy synth or processed piano note",
      "section_jobs": [
        {"section_id": "infiltration", "intent": "two-note motif, sparse, breathy", "density": "sparse"},
        {"section_id": "near_miss", "intent": "motif absent, negative space", "density": "sparse"},
        {"section_id": "decision", "intent": "motif returns in higher register, urgent", "density": "medium"},
        {"section_id": "sprint", "intent": "motif develops into short repeated phrase, syncopated", "density": "dense"},
        {"section_id": "cut", "intent": "single motif note, abruptly cut", "density": "sparse"}
      ]
    },
    {
      "id": "impact_layer",
      "name": "Impact Layer",
      "role": "percussion",
      "register": {"low": 36, "high": 60},
      "instrument_hint": "sub impacts, explosions, riser hits",
      "section_jobs": [
        {"section_id": "infiltration", "intent": "occasional low impact on bar 4 and 8", "density": "sparse"},
        {"section_id": "near_miss", "intent": "silence except one distant impact", "density": "sparse"},
        {"section_id": "decision", "intent": "riser hit at decision end", "density": "sparse"},
        {"section_id": "sprint", "intent": "impacts on phrase starts, every 2 bars", "density": "medium"},
        {"section_id": "cut", "intent": "hard impact on final downbeat", "density": "sparse"}
      ]
    },
    {
      "id": "texture",
      "name": "Texture",
      "role": "texture",
      "register": {"low": 48, "high": 96},
      "instrument_hint": "filtered noise, granular shimmer, air",
      "section_jobs": [
        {"section_id": "infiltration", "intent": "filtered noise bed, low volume, swells", "density": "sparse"},
        {"section_id": "near_miss", "intent": "remove texture, only air", "density": "sparse"},
        {"section_id": "decision", "intent": "reintroduce as rising filtered sweep", "density": "medium"},
        {"section_id": "sprint", "intent": "full noise with rhythmic gating", "density": "dense"},
        {"section_id": "cut", "intent": "abrupt noise burst cut", "density": "sparse"}
      ]
    }
  ],
  "motif_strategy": "Two-note descending minor 2nd in A minor, first heard in infiltration, omitted in near miss, returns transposed up a fourth in decision, fragmented and syncopated in sprint, final statement cut off.",
  "harmony_strategy": "A minor drone with alternating i - bVI in infiltration; near miss reduces to single A minor cluster; decision uses i - V/iv; sprint uses power chords or minor stabs A5, F5, G5 with chromatic passing; cut ends on unresolved tritone or minor 2nd.",
  "groove_strategy": "Hierarchy: sub pulse anchors low end, muted percussion carries mid syncopation, high tick supplies upper 16th subdivision. Sparse in infiltration, negative space in near miss, building in decision, dense but broken in sprint, hard stop in cut. Avoid continuous ostinato; use gaps every 2-4 bars."
}
